var color = $("#F1PCC_target").attr("fill");
var red = "rgb(255, 0, 0)";
var green = "rgb(0, 255, 0)";
var requestedAction = "";
var out_color = "";
if (color == "green"){
    $("#F1PCC_target").attr("fill","red");
    requestedAction = "CLOSE";
    out_color = "red";
}
else if (color == "red"){
    $("#F1PCC_target").attr("fill","green");
    requestedAction = "OPEN";
    out_color = "green";
}

// color = $("#PCC1")[0].style.fill;

//$("#PCC1")[0].style.fill = color;
var payload = {
    "event": "relay_click",
    "requestedRelay": "F1PCC",
    "requestedAction": requestedAction,
    "color": out_color
    };
$scope.send({payload: payload, topic: 'mg/event'})

